    const onPointerMove = (event: PointerEvent) => {
      if (pointerId !== event.pointerId) {
        return;
      }
      const delta = event.clientY - originY;
      if (!isDraggingRef.current) {
        if (Math.abs(delta) < DRAG_SLOP) {
          return;
