  id,
  inputRef,
  value,
  onChange,
  placeholder,
  min,
  max,
  isDateDisabled,
  isEffectivelyDisabled,
  isFocusableDisabled,
  isEffectivelyRequired,
  isBusy,
  statusType,
  ariaDescribedBy,
  controlProps,
}: NativeDateSegmentProps) {
  const {
    onFocus: onFocusProp,
    onBlur: onBlurProp,
    ...inputProps
  } = controlProps ?? {};
