  slot: {
    position: 'relative',
    display: 'flex',
    alignItems: 'center',
    flex: 1,
    minInlineSize: 0,
  },
  overlay: {
    position: 'absolute',
    insetInlineStart: 0,
    insetInlineEnd: 0,
    insetBlock: 0,
    display: 'block',
    // The same iOS-only floor as the input it covers, shared baselines.
    fontSize: {
      default: typeScaleVars['--text-body-size'],
      '@media (pointer: coarse)': {
        '@supports (-webkit-touch-callout: none)': `max(1rem, ${typeScaleVars['--text-body-size']})`,
      },
