    if (!isElement(node)) {
      continue;
    }
    const style = view.getComputedStyle(node);
    if (readsTouchAction) {
      const pans = parseTouchAction(style.touchAction || 'auto');
      allowX &&= pans.x;
      allowY &&= pans.y;
