          this.runStart = this.previous;
        }
        this.run += 1;
      } else {
        this.run = 0;
      }
      if (this.run >= LIFT_RUN && step <= this.runStart * LIFT_DECAY) {
        this.phase = 'momentum';
        liftNow = true;
      }
    }
    if (steps === 1 && this.count > 0 && this.previous > 0 && step > 0) {
      this.ratio = Math.min(1, Math.max(0.5, step / this.previous));
    }
