/** The timing function for `points`: maps time progress to eased progress. */
export function cubicBezier([x1, y1, x2, y2]: BezierPoints): (
  x: number,
) => number {
  const cx = 3 * x1;
  const bx = 3 * (x2 - x1) - cx;
