    peeled = false;
    if (isPM === null) {
      const period = dayPeriods.find(({word}) => strip(word));
      if (period !== undefined) {
        isPM = period.isPM;
        peeled = true;
      }
    }
    if (edgeWords.some(strip)) {
      peeled = true;
    }
